<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller; use App\Models\Opportunity; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class OpportunityController extends Controller {
 public function index(Request $request) { $q=Opportunity::with(['catalogImages'=>fn($images)=>$images->where('is_public',true)])->where('status','published')->whereNotNull('published_at')->where(function($q){$q->whereNull('deadline_at')->orWhere('deadline_at','>=',now());}); $term=trim((string)$request->query('q','')); if($term!=='')$q->where(fn($w)=>$w->where('title','like',"%$term%")->orWhere('organization','like',"%$term%")->orWhere('summary','like',"%$term%")); if($request->filled('category'))$q->where('category',$request->query('category')); if($request->filled('country'))$q->where('country_name','like','%'.trim($request->query('country')).'%'); if($request->filled('city'))$q->where('city','like','%'.trim($request->query('city')).'%'); if($request->filled('opportunity_type'))$q->where('opportunity_type','like','%'.trim($request->query('opportunity_type')).'%'); if($request->boolean('remote'))$q->where('is_remote',true); return response()->json($q->latest('published_at')->paginate(min(30, max(1, (int) $request->query('per_page', 12))))); }
 public function show(string $slug) { $item=Opportunity::with(['catalogImages'=>fn($images)=>$images->where('is_public',true)])->where('slug',$slug)->where('status','published')->whereNotNull('published_at')->firstOrFail(); return response()->json(['data'=>$item]); }
 public function store(Request $request) { $data=$request->validate(['title'=>['required','string','max:200'],'organization'=>['required','string','max:180'],'category'=>['required',Rule::in(['Emploi','Bourse','Formation','Financement','Mission','Concours','Service','Autre'])],'opportunity_type'=>['nullable','string','max:60'],'country_name'=>['nullable','string','max:120'],'city'=>['nullable','string','max:120'],'is_remote'=>['sometimes','boolean'],'summary'=>['required','string','max:600'],'description'=>['required','string','max:12000'],'requirements'=>['nullable','string','max:8000'],'benefits'=>['nullable','string','max:8000'],'application_url'=>['nullable','url','max:2048'],'contact_email'=>['nullable','email','max:190'],'contact_phone'=>['nullable','string','max:40'],'deadline_at'=>['nullable','date','after:today']]); $this->ensureContact($request); $data['user_id']=$request->user()->id; $data['slug']=Str::slug($data['title']).'-'.Str::lower(Str::random(6)); $data['status']='pending_review'; $item=Opportunity::create($data); return response()->json(['message'=>'Opportunité envoyée à OCD pour validation.','data'=>$item],201); }
 public function uploadCatalog(Request $request,int $opportunity) { $item=Opportunity::where('user_id',$request->user()->id)->findOrFail($opportunity); $data=$request->validate(['images'=>['required','array','min:1','max:12'],'images.*'=>['required','image','mimes:jpg,jpeg,png,webp','max:5120'],'captions'=>['sometimes','array'],'captions.*'=>['nullable','string','max:180']]); $created=[]; foreach($request->file('images',[]) as $i=>$file){ $path=$file->store('catalogues/opportunities','public'); $created[]=$item->catalogImages()->create(['uploaded_by'=>$request->user()->id,'image_path'=>$path,'caption'=>$data['captions'][$i]??null,'is_public'=>false]); } return response()->json(['message'=>'Pièces justificatives ajoutées. Elles seront visibles après validation de l’offre.','data'=>$created],201); }
 public function updateOwn(Request $request,int $opportunity) {
  $item=Opportunity::where('user_id',$request->user()->id)->findOrFail($opportunity);
  $data=$request->validate(['title'=>['sometimes','required','string','max:200'],'organization'=>['sometimes','required','string','max:180'],'category'=>['sometimes','required',Rule::in(['Emploi','Bourse','Formation','Financement','Mission','Concours','Service','Autre'])],'opportunity_type'=>['nullable','string','max:60'],'country_name'=>['nullable','string','max:120'],'city'=>['nullable','string','max:120'],'is_remote'=>['sometimes','boolean'],'summary'=>['sometimes','required','string','max:600'],'description'=>['sometimes','required','string','max:12000'],'requirements'=>['nullable','string','max:8000'],'benefits'=>['nullable','string','max:8000'],'application_url'=>['nullable','url','max:2048'],'contact_email'=>['nullable','email','max:190'],'contact_phone'=>['nullable','string','max:40'],'deadline_at'=>['nullable','date']]);
  if(array_key_exists('application_url',$data)||array_key_exists('contact_email',$data)||array_key_exists('contact_phone',$data)) { if(blank($data['application_url']??$item->application_url)&&blank($data['contact_email']??$item->contact_email)&&blank($data['contact_phone']??$item->contact_phone)) return response()->json(['message'=>'Conservez au moins un moyen de contact.'],422); }
  // Une modification d’une annonce déjà publiée doit repasser en modération afin que les changements soient contrôlés.
  if($item->status==='published') { $data['status']='pending_review'; $data['published_at']=null; $item->catalogImages()->update(['is_public'=>false]); }
  $item->fill($data); if(isset($data['title']) && $data['title']!==$item->getOriginal('title')) $item->slug=Str::slug($data['title']).'-'.Str::lower(Str::random(6)); $item->save();
  return response()->json(['message'=>'Opportunité modifiée. '.($item->status==='pending_review'?'Elle repasse en modération avant publication.':'') ,'data'=>$item->fresh()]);
 }
 public function deleteOwn(Request $request,int $opportunity) { $item=Opportunity::where('user_id',$request->user()->id)->findOrFail($opportunity); foreach($item->catalogImages as $image) { \Illuminate\Support\Facades\Storage::disk('public')->delete($image->image_path); $image->delete(); } $item->delete(); return response()->json(['message'=>'Votre opportunité a été supprimée.']); }
 public function my(Request $request) { return response()->json(['data'=>Opportunity::where('user_id',$request->user()->id)->withCount('applications')->latest()->get()]); }
 public function myOpportunityApplications(Request $request,int $opportunity) { $item=Opportunity::where('user_id',$request->user()->id)->findOrFail($opportunity); $rows=$item->applications()->with(['user:id,name,email','user.profile.country:id,name'])->latest('submitted_at')->get()->map(fn($a)=>['id'=>$a->id,'status'=>$a->status,'submitted_at'=>$a->submitted_at,'cover_message'=>$a->cover_message,'candidate'=>['id'=>$a->user?->id,'name'=>$a->user?->name,'email'=>$a->user?->email,'public_name'=>$a->user?->profile?->public_name,'professional_title'=>$a->user?->profile?->professional_title,'phone'=>$a->user?->profile?->phone,'city'=>$a->user?->profile?->city,'country'=>$a->user?->profile?->country?->name]]); return response()->json(['data'=>$rows,'opportunity'=>['id'=>$item->id,'title'=>$item->title,'status'=>$item->status]]); }
 public function apply(Request $request,string $slug) {
  $item=Opportunity::where('slug',$slug)->where('status','published')->where(function($q){$q->whereNull('deadline_at')->orWhere('deadline_at','>=',now());})->firstOrFail();
  $user=$request->user();
  abort_if($user->account_type==='organization',403,'Les comptes organisation ne peuvent pas candidater. Connectez-vous avec un compte candidat.');
  abort_if((int)$item->user_id===(int)$user->id,403,'C’est votre offre : vous ne pouvez pas candidater à votre propre publication.');
  // Vérifier d’abord les candidatures existantes : une candidature déjà enregistrée reste reconnue même si le profil a changé depuis.
  $existing=$item->applications()->where('user_id',$user->id)->first();
  if($existing) return response()->json(['message'=>'Vous avez déjà candidaté à cette opportunité.','data'=>$existing,'already_applied'=>true],409);
  abort_unless($user->profile && $user->profile->review_status==='approved',403,'Votre profil OCD doit être approuvé avant de candidater. Ouvrez Mon profil, complétez les informations demandées puis soumettez-le à validation.');
  $data=$request->validate(['cover_message'=>['nullable','string','max:5000']]);
  $application=$item->applications()->create(['user_id'=>$user->id,'cover_message'=>$data['cover_message']??null,'status'=>'submitted','submitted_at'=>now()]);
  \App\Models\OcdNotification::create(['user_id'=>$item->user_id,'type'=>'new_application','title'=>'Nouvelle candidature reçue','message'=>$user->name.' a candidaté à votre opportunité « '.$item->title.' ».','data'=>['application_id'=>$application->id,'opportunity_id'=>$item->id,'candidate_id'=>$user->id]]);
  return response()->json(['message'=>'Candidature enregistrée dans OCD.','data'=>$application],201);
 }
 public function applications(Request $request) { return response()->json(['data'=>$request->user()->applications()->with('opportunity:id,title,slug,organization,category')->latest()->get()]); }

 public function adminOpportunityApplications(Request $request,int $opportunity) { $item=Opportunity::findOrFail($opportunity); $rows=$item->applications()->with(['user:id,name,email','user.profile.country:id,name'])->latest('submitted_at')->limit(200)->get()->map(fn($a)=>['id'=>$a->id,'status'=>$a->status,'submitted_at'=>$a->submitted_at,'cover_message'=>$a->cover_message,'candidate'=>['id'=>$a->user?->id,'name'=>$a->user?->name,'email'=>$a->user?->email,'public_name'=>$a->user?->profile?->public_name,'professional_title'=>$a->user?->profile?->professional_title,'phone'=>$a->user?->profile?->phone,'city'=>$a->user?->profile?->city,'country'=>$a->user?->profile?->country?->name]]); return response()->json(['data'=>$rows,'opportunity'=>['id'=>$item->id,'title'=>$item->title,'status'=>$item->status]]); }
 public function adminIndex(Request $request) { $q=Opportunity::query()->with('owner:id,name,email')->withCount('applications'); if($request->filled('q')){$term=trim((string)$request->query('q'));$q->where(fn($w)=>$w->where('title','like',"%$term%")->orWhere('organization','like',"%$term%"));} foreach(['category','status','country_name','city'] as $field)if($request->filled($field))$q->where($field,'like','%'.trim((string)$request->query($field)).'%'); if($request->filled('from'))$q->whereDate('created_at','>=',$request->query('from'));if($request->filled('to'))$q->whereDate('created_at','<=',$request->query('to'));return response()->json($q->latest()->paginate(min(100,max(1,(int)$request->query('per_page',50))))); }
 public function adminUpdate(Request $request,int $opportunity) {
  $item=Opportunity::findOrFail($opportunity);
  $d=$request->validate(['status'=>['sometimes',Rule::in(['published','pending_review','rejected','suspended','archived','changes_requested'])],'review_note'=>['nullable','string','max:2000'],'title'=>['sometimes','string','max:200'],'category'=>['sometimes',Rule::in(['Emploi','Bourse','Formation','Financement','Mission','Concours','Service','Autre'])],'country_name'=>['nullable','string','max:120'],'city'=>['nullable','string','max:120'],'deadline_at'=>['nullable','date'],'summary'=>['sometimes','string','max:600'],'contact_email'=>['nullable','email','max:190'],'contact_phone'=>['nullable','string','max:40'],'application_url'=>['nullable','url','max:2048']]);
  $oldStatus=$item->status; $newStatus=$d['status']??$oldStatus;
  if(in_array($newStatus,['rejected','changes_requested','suspended'],true) && blank($d['review_note']??$item->review_note)) return response()->json(['message'=>'Un motif est obligatoire pour ce statut.','errors'=>['review_note'=>['Veuillez renseigner le motif de la décision.']]],422);
  if(($d['status']??null)==='published' && !$item->published_at)$d['published_at']=now();
  if(isset($d['status']) && in_array($newStatus,['suspended','archived','rejected','pending_review','changes_requested'],true))$d['published_at']=null;
  if(isset($d['status']) && $newStatus!==$oldStatus){$d['reviewed_at']=now();$d['reviewed_by']=$request->user()->id;}
  $item->update($d);
  if(isset($d['status']) && $newStatus!==$oldStatus){
   \App\Models\OpportunityReviewLog::create(['opportunity_id'=>$item->id,'reviewer_id'=>$request->user()->id,'action'=>$newStatus,'note'=>$d['review_note']??null,'metadata'=>['previous_status'=>$oldStatus,'source'=>'admin_all_offers']]);
   $labels=['published'=>'publiée','pending_review'=>'remise en attente','rejected'=>'refusée','suspended'=>'suspendue','archived'=>'archivée','changes_requested'=>'à corriger'];
   \App\Models\OcdNotification::create(['user_id'=>$item->user_id,'type'=>'opportunity_status_'.$newStatus,'title'=>'Statut de votre opportunité mis à jour','message'=>'Votre opportunité « '.$item->title.' » a été '.$labels[$newStatus].'.'.(filled($d['review_note']??null)?' Motif : '.($d['review_note']):''),'data'=>['opportunity_id'=>$item->id,'status'=>$newStatus]]);
  }
  return response()->json(['message'=>'Offre mise à jour.','data'=>$item->fresh()]);
 }

 private function ensureContact(Request $request): void { if (!$request->filled('application_url') && !$request->filled('contact_email') && !$request->filled('contact_phone')) abort(response()->json(['message'=>'Ajoutez au moins un lien de candidature, un e-mail ou un numéro de téléphone de contact.','errors'=>['contact_phone'=>['Un moyen de contact est obligatoire.']]],422)); }
 public function adminStore(Request $request) {
  $data=$request->validate(['title'=>['required','string','max:200'],'organization'=>['required','string','max:180'],'category'=>['required',Rule::in(['Emploi','Bourse','Formation','Financement','Mission','Concours','Service','Autre'])],'opportunity_type'=>['nullable','string','max:60'],'country_name'=>['nullable','string','max:120'],'city'=>['nullable','string','max:120'],'is_remote'=>['sometimes','boolean'],'summary'=>['required','string','max:600'],'description'=>['required','string','max:12000'],'requirements'=>['nullable','string','max:8000'],'benefits'=>['nullable','string','max:8000'],'application_url'=>['nullable','url','max:2048'],'contact_email'=>['nullable','email','max:190'],'contact_phone'=>['nullable','string','max:40'],'deadline_at'=>['nullable','date','after:today']]);
  $this->ensureContact($request); $data['user_id']=$request->user()->id; $data['slug']=Str::slug($data['title']).'-'.Str::lower(Str::random(6)); $data['status']='published'; $data['published_at']=now();
  $item=Opportunity::create($data); return response()->json(['message'=>'Publication créée et visible sur le site public.','data'=>$item],201);
 }
}
